<dialog id="confirmation" aria-labelledby="confirm-title" aria-describedby="confirm-description"><div class="p-7"><span class="inline-flex rounded-xl bg-amber-50 p-3 text-amber-800"><x-icon name="warning-circle" /></span><h2 id="confirm-title" class="mt-4 text-xl">Confirm this change</h2><p id="confirm-description" data-confirm-message class="mt-3 text-sm leading-6 text-slate-500"></p><div class="mt-7 flex justify-end gap-3"><button type="button" class="btn btn-secondary" data-close-dialog autofocus>Cancel</button><button type="button" class="btn btn-primary" data-confirm-accept>Confirm change</button></div></div></dialog>
